	defer runtime.UnlockOSThread()

	raw := C.batch_dleq_proof_new(
		(**C.C_BlindedToken)(unsafe.Pointer(&cBlindedTokens[0])),
		(**C.C_SignedToken)(unsafe.Pointer(&cSignedTokens[0])),
