      .set('Accept', 'application/json')
      .set('Content-Type', 'application/json')
  }
}

function merge(a, b) {
  return _.merge(a, b, customizer)

  function customizer(objValue, srcValue) {
    if (_.isArray(objValue)) {
      return _.uniq(objValue.concat(srcValue))
    }
  }
}

